import type { Readable } from "node:stream";

/**
 * F08-BKP-02 (#38): private storage of backup binaries, outside PostgreSQL.
 *
 * Keys are generated by the server (UUID v4); no client value ever becomes a
 * key or a path. An object becomes visible only through `commit`: a failed or
 * incomplete transfer never replaces or shadows a committed object.
 */
export interface BackupStorage {
  /**
   * Writes `source` into a private staging area that no read can see. The
   * caller verifies size and hash on the stream itself and then commits or
   * discards. If `source` fails, the staged bytes are removed and the error
   * is rethrown.
   */
  stage(key: string, source: Readable): Promise<StagedBackupObject>;

  /** Bytes of a committed object; `BackupObjectMissingError` if absent. */
  open(key: string): Promise<{ sizeBytes: number; stream: Readable }>;

  /** Removes a committed object. Removing an absent object is not an error. */
  remove(key: string): Promise<void>;

  /** Removes a staged object left behind (e.g. an abandoned upload). */
  discardStaged(key: string): Promise<void>;
}

export interface StagedBackupObject {
  /** Makes the object visible under its key, atomically. */
  commit(): Promise<void>;
  /** Removes the staged bytes. Idempotent. */
  discard(): Promise<void>;
}

export class BackupObjectMissingError extends Error {
  constructor() {
    super("BACKUP_OBJECT_MISSING");
  }
}

export const BACKUP_STORAGE = Symbol("BACKUP_STORAGE");

const UUID_V4 = /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/;

/** Storage keys are server-generated UUID v4, never paths. */
export function assertStorageKey(key: string): void {
  if (!UUID_V4.test(key)) throw new Error("Invalid backup storage key");
}

/** A file found in the private storage, for the inventory (F10, #40). */
export interface StoredBackupFile {
  area: "objects" | "staging";
  /** File name inside its area; never a path. */
  name: string;
  /** Storage key the name belongs to, or null if it does not follow the layout. */
  key: string | null;
  sizeBytes: number;
  modifiedAt: Date;
}

/**
 * Optional capability of an adapter: list what it stores and remove leftover
 * staging files. Used only by the operator inventory (`backups:inventory`),
 * never by the API.
 */
export interface BackupStorageInventory {
  list(): Promise<StoredBackupFile[]>;
  /** Removes `staging/<name>` if it is a staging file. Idempotent. */
  removeStagedFile(name: string): Promise<void>;
}

const STAGING_NAME = /^([0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12})\.[0-9a-f]{16}\.part$/;

/** Storage key of a staging file name, or null if it is not one. */
export function stagingKey(name: string): string | null {
  return STAGING_NAME.exec(name)?.[1] ?? null;
}

/** Storage key of an object file name, or null if it is not one. */
export function objectKey(name: string): string | null {
  return UUID_V4.test(name) ? name : null;
}
